{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "name": "Healthcare Research Data",
    "operation": "add",
    "widgets_json": {
      "trial_catalysts": {
        "name": "Trial Catalysts",
        "description": "Upcoming clinical trial readouts.",
        "endpoint": "/trial-catalysts",
        "type": "table",
        "w": 20,
        "h": 9,
        "params": [
          {
            "paramName": "ticker",
            "type": "endpoint",
            "label": "Ticker",
            "optionsEndpoint": "/tickers",
            "value": "PFE",
            "multiSelect": false
          }
        ],
        "data": {
          "table": {
            "columnsDefs": [
              {
                "field": "ticker",
                "headerName": "Ticker",
                "cellDataType": "text"
              },
              {
                "field": "phase",
                "headerName": "Phase",
                "cellDataType": "text"
              },
              {
                "field": "readout_date",
                "headerName": "Readout",
                "cellDataType": "dateString"
              }
            ]
          }
        },
        "staleTime": 900000
      },
      "catalyst_metric": {
        "name": "Catalysts 30d",
        "description": "Catalysts in the next 30 days.",
        "endpoint": "/catalyst-count",
        "type": "metric",
        "w": 6,
        "h": 4,
        "staleTime": 900000
      },
      "pipeline_chart": {
        "name": "Pipeline by Phase",
        "description": "Plotly pipeline distribution by phase.",
        "endpoint": "/pipeline-by-phase",
        "type": "chart",
        "w": 20,
        "h": 9,
        "params": [
          {
            "paramName": "raw",
            "type": "text",
            "value": "true"
          }
        ],
        "staleTime": 900000
      }
    },
    "apps_json": [
      {
        "name": "Trial Desk",
        "description": "Catalysts on tap.",
        "tabs": {
          "trials": {
            "id": "trials",
            "name": "Trials",
            "layout": [
              {
                "i": "trial_catalysts",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          },
          "posture": {
            "id": "posture",
            "name": "Posture",
            "layout": [
              {
                "i": "catalyst_metric",
                "x": 0,
                "y": 0,
                "w": 12,
                "h": 6
              }
            ]
          }
        }
      }
    ]
  }
}

